#!/usr/bin/env python3
"""Plot training progress from the CSV generated by analyze_grad_progress.py"""

import pandas as pd
import matplotlib.pyplot as plt
import sys
import numpy as np

if len(sys.argv) < 2:
    print("Usage: python plot_grad_progress.py <csv_file>")
    sys.exit(1)

csv_file = sys.argv[1]
df = pd.read_csv(csv_file)

# Create cumulative iteration counter across scales
df = df.sort_values(['scale', 'iteration'])
df['scale_float'] = df['scale'].astype(float)

# Group by scale to create cumulative iteration
df['cum_iter'] = df.groupby('scale').cumcount() + 1

# Create plot
fig, ax = plt.subplots(figsize=(14, 6))

# Get unique scales
scales = sorted(df['scale_float'].unique(), reverse=True)

# Color map for scales
colors = plt.cm.viridis(np.linspace(0, 1, len(scales)))
color_map = dict(zip(scales, colors))

# Plot each scale segment
for scale in scales:
    scale_data = df[df['scale_float'] == scale].sort_values('iteration')
    ax.plot(scale_data['iteration'], scale_data['mean_e2e'], 
            'o-', label=f'Scale {scale}', color=color_map[scale], markersize=4)

ax.set_xlabel('Iteration within Scale')
ax.set_ylabel('Mean E2E (s)')
ax.set_title(f'Training Progress: {csv_file.replace("_training_progress.csv", "")}')
ax.legend(loc='upper right', fontsize=8)
ax.grid(True, alpha=0.3)
ax.set_yscale('log')

# Add scale labels
plt.tight_layout()
output = csv_file.replace('.csv', '.png')
plt.savefig(output, dpi=150)
print(f"Saved: {output}")

# Also create a cumulative view
fig2, ax2 = plt.subplots(figsize=(14, 6))

# Cumulative iteration
cumsum = 0
x_vals = []
y_vals = []
labels = []

for scale in scales:
    scale_data = df[df['scale_float'] == scale].sort_values('iteration')
    n = len(scale_data)
    x_vals.extend(scale_data['iteration'].values)
    y_vals.extend(scale_data['mean_e2e'].values)
    labels.extend([f'Scale {scale}'] * n)

ax2.scatter(range(len(y_vals)), y_vals, c=labels, cmap='viridis', s=20, alpha=0.7)
ax2.set_xlabel('Cumulative Iteration')
ax2.set_ylabel('Mean E2E (s)')
ax2.set_title(f'Training Progress (Cumulative): {csv_file.replace("_training_progress.csv", "")}')
ax2.set_yscale('log')
ax2.grid(True, alpha=0.3)

# Add vertical lines at scale boundaries
cumsum = 0
for scale in scales:
    scale_data = df[df['scale_float'] == scale]
    n = len(scale_data)
    cumsum += n
    ax2.axvline(x=cumsum, color='red', linestyle='--', alpha=0.5)

plt.tight_layout()
output2 = csv_file.replace('.csv', '_cumulative.png')
plt.savefig(output2, dpi=150)
print(f"Saved: {output2}")
